from __future__ import annotations

import argparse
import hashlib
import importlib.util
import json
import re
import sys
from collections import defaultdict
from pathlib import Path

ROOT = Path(__file__).resolve().parents[3]
OUT = Path(__file__).resolve().parent
LAYOUTS = ROOT / "scratch/t05/layouts.json"
READER_WIDTHS = ROOT / "scratch/t05/reader_widths.json"

CMP_PREFIXES = tuple(bytes((0x81, x)) for x in (0xFA, 0xFB, 0xF9, 0xF8, 0xFE, 0xFF, 0xFD, 0xFC)) + (b"\x3d",)
BUF_REGS = {"rsi", "rdi", "rcx", "rbx", "rdx", "r8", "r9", "r12", "r13", "r14", "r15"}
OFF_MIN, OFF_MAX = 0x20, 0x400
SIZE = {"byte": 1, "word": 2, "dword": 4, "qword": 8}
RE_READ = re.compile(r"^(?:mov|movzx|movsx|movsxd|movss|movsd)\s+([a-z0-9]+),\s*(byte|word|dword|qword)?\s*ptr\s*\[([a-z0-9]+)(?:\s*\+\s*(0x[0-9a-f]+))?\]$")
RE_WRITE = re.compile(r"^mov\s+(byte|word|dword|qword)\s+ptr\s*\[([a-z0-9]+)(?:\s*\+\s*(0x[0-9a-f]+))?\],\s*([a-z0-9]+)$")
RE_LEA = re.compile(r"^([a-z0-9]+),\s*\[([a-z0-9]+)(?:\s*\+\s*(0x[0-9a-f]+))?\]$")
RE_MOV_REG = re.compile(r"^([a-z0-9]+),\s*([a-z0-9]+)$")
RE_IMM_CMP = re.compile(r"^([a-z0-9]+),\s*0x([0-9a-f]+)$")


def load_pe():
    spec = importlib.util.spec_from_file_location("t05_pe", ROOT / "scripts/t05_pe.py")
    if spec is None or spec.loader is None:
        raise RuntimeError("cannot load scripts/t05_pe.py")
    module = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(module)
    return module.default()


def code_from_imm(imm: bytes) -> str | None:
    chars = imm[::-1]
    if len(chars) != 4 or not all((48 <= c <= 57) or (65 <= c <= 90) or (97 <= c <= 122) for c in chars):
        return None
    return chars.decode("ascii")


def decode_cmp_hits(pe):
    from capstone import CS_ARCH_X86, CS_MODE_64, Cs
    md = Cs(CS_ARCH_X86, CS_MODE_64)
    raw = pe.raw
    hits = []
    for sec in pe._secs:
        if not sec["exec"] or not sec["rawsize"]:
            continue
        start = sec["raw"]
        end = min(start + sec["rawsize"], len(raw))
        for prefix in CMP_PREFIXES:
            pos = start
            while True:
                pos = raw.find(prefix, pos, end)
                if pos < 0:
                    break
                imm_at = pos + len(prefix)
                if imm_at + 4 <= end:
                    code = code_from_imm(raw[imm_at:imm_at + 4])
                    if code:
                        va = pe.f2va(pos)
                        decoded = list(md.disasm(raw[pos:pos + 12], va or 0)) if va else []
                        if decoded and decoded[0].mnemonic == "cmp":
                            m = RE_IMM_CMP.match(decoded[0].op_str.lower())
                            if m and int(m.group(2), 16) == int.from_bytes(raw[imm_at:imm_at + 4], "little"):
                                hits.append((pos, code, va, decoded[0]))
                pos += 1
    hits.sort(key=lambda x: x[0])
    # Search patterns are disjoint, but retain deterministic unique locations defensively.
    unique = {}
    for h in hits:
        unique[(h[0], h[1])] = h
    return list(unique.values()), md


def access_of(ins):
    """Return narrow direct member access (offset,size,kind,description); qword reads are rejected."""
    text = (ins.mnemonic + " " + ins.op_str).lower()
    m = RE_READ.match(text)
    if m and m.group(3) in BUF_REGS:
        size = SIZE.get(m.group(2) or "dword", 4)
        off = int(m.group(4), 16) if m.group(4) else 0
        if OFF_MIN <= off <= OFF_MAX and size in (1, 2, 4):
            # A 64-bit destination from a qword member is an object pointer, not a field value.
            return off, size, "read", f"{ins.mnemonic} {ins.op_str}"
    m = RE_WRITE.match(text)
    if m and m.group(2) in BUF_REGS:
        size = SIZE[m.group(1)]
        off = int(m.group(3), 16) if m.group(3) else 0
        if OFF_MIN <= off <= OFF_MAX and size in (1, 2, 4):
            return off, size, "write", f"{ins.mnemonic} {ins.op_str}"
    return None


def conditional_target(ins):
    if ins.mnemonic not in {"je", "jz", "jne", "jnz", "ja", "jae", "jb", "jbe", "jg", "jge", "jl", "jle", "js", "jns", "jo", "jno", "jp", "jnp"}:
        return None
    try:
        return int(ins.op_str.strip(), 0)
    except ValueError:
        return None


def target_accesses(pe, md, target_va, max_span=0x600):
    """Walk reachable local getter blocks, honoring direct branches and returns."""
    first_off = pe.va2f(target_va)
    if first_off is None:
        return []
    q = [(target_va, 0)]
    seen = set()
    found = []
    while q and len(seen) < 24:
        block_va, depth = q.pop(0)
        if block_va in seen or abs(block_va - target_va) > max_span:
            continue
        seen.add(block_va)
        file_off = pe.va2f(block_va)
        if file_off is None:
            continue
        for ins in md.disasm(pe.raw[file_off:file_off + 0x100], block_va):
            acc = access_of(ins)
            if acc:
                found.append((depth, ins.address, acc))
            if ins.mnemonic == "ret":
                break
            if ins.mnemonic == "jmp":
                try:
                    jva = int(ins.op_str.strip(), 0)
                except ValueError:
                    break
                if abs(jva - target_va) <= max_span:
                    q.append((jva, depth + 1))
                break
            jva = conditional_target(ins)
            if jva is not None:
                if abs(jva - target_va) <= max_span:
                    q.append((jva, depth + 1))
                q.append((ins.address + ins.size, depth + 1))
                break
        # Do not keep following arbitrary code after the requested basic block.
    found.sort(key=lambda h: (h[0], h[1]))
    return found


def fallthrough_writes(pe, md, branch, code):
    if branch.mnemonic not in ("jne", "jnz"):
        return []
    start_va = branch.address + branch.size
    off = pe.va2f(start_va)
    if off is None:
        return []
    out = []
    insns = list(md.disasm(pe.raw[off:off + 0x180], start_va))
    for ins in insns[:64]:
        if ins.mnemonic == "cmp":
            m = RE_IMM_CMP.match(ins.op_str.lower())
            if m:
                val = int(m.group(2), 16)
                if code_from_imm(val.to_bytes(4, "little")):
                    break
        acc = access_of(ins)
        if acc and acc[2] == "write":
            out.append((0, ins.address, acc))
        if ins.mnemonic == "ret":
            break
    return out


def find_candidates(pe, hits, md):
    from capstone import CS_ARCH_X86, CS_MODE_64, Cs
    # `md` is the same engine used for the scans; keeping helper explicit makes selftest straightforward.
    raw_candidates = []
    for file_off, code, cmp_va, cmp_ins in hits:
        start_off = pe.va2f(cmp_va)
        if start_off is None:
            continue
        block = list(md.disasm(pe.raw[start_off:start_off + 0x20], cmp_va))
        branch = next((x for x in block[1:4] if x.mnemonic in ("je", "jz", "jne", "jnz")), None)
        if branch is None:
            continue
        if branch.mnemonic in ("je", "jz"):
            try:
                tgt = int(branch.op_str.strip(), 0)
            except ValueError:
                tgt = None
            if tgt is not None:
                for depth, access_va, acc in target_accesses(pe, md, tgt):
                    if acc[2] != "read":
                        continue
                    score = 0.91 - min(depth, 4) * 0.025
                    if acc[3].startswith("movss "):
                        score += 0.02
                    raw_candidates.append(make_record(pe, file_off, code, acc, access_va, "getter", depth, score))
                    # A normal getter usually exposes one direct property. Keep at most three branch paths per cmp.
                    if len([r for r in raw_candidates if r["file_off"] == hex(file_off) and r["code"] == code]) >= 3:
                        break
        if branch.mnemonic in ("jne", "jnz"):
            for depth, access_va, acc in fallthrough_writes(pe, md, branch, code):
                raw_candidates.append(make_record(pe, file_off, code, acc, access_va, "setter", depth, 0.82))
    # De-duplicate identical evidence from overlapping byte patterns / CFG paths.
    best = {}
    for rec in raw_candidates:
        k = (rec["code"], rec["file_off"], rec["object_off"], rec["size"], rec["kind"])
        if k not in best or rec["score"] > best[k]["score"]:
            best[k] = rec
    return list(best.values())


def make_record(pe, file_off, code, access, access_va, route, depth, score):
    off, size, kind, insn = access
    route_text = f"je 目标块" if route == "getter" else "jne fall-through"
    if depth:
        route_text += f"（CFG 深度 {depth}）"
    return {
        "code": code,
        "file_off": hex(file_off),
        "object_off": off,
        "size": size,
        "kind": kind,
        "access_va": hex(access_va),
        "score": round(score, 3),
        "why": f"{route_text}内 {insn}",
        "section": pe.section_of(file_off),
        "_match_route": route,
    }


def reader_objects(pe, md, body_off, scan_bytes=0x3000):
    """Recover obj+offset for each reader call, including LEA aliases passed through RDX."""
    va = pe.f2va(body_off)
    if va is None:
        return []
    aliases = {}
    widths = []
    objects = []
    last_width = None
    for ins in md.disasm(pe.raw[body_off:body_off + scan_bytes], va):
        m = RE_LEA.match(ins.op_str.lower()) if ins.mnemonic == "lea" else None
        if m:
            dst, _base, disp = m.groups()
            aliases[dst] = int(disp, 16) if disp else 0
            continue
        m = RE_MOV_REG.match(ins.op_str.lower()) if ins.mnemonic == "mov" else None
        if m:
            dst, src = m.groups()
            if src in aliases:
                aliases[dst] = aliases[src]
            else:
                aliases.pop(dst, None)
        if ins.mnemonic == "mov" and ins.op_str.lower().startswith("r8d,"):
            try:
                last_width = int(ins.op_str.split(",", 1)[1].strip(), 0)
            except ValueError:
                last_width = None
        if ins.mnemonic == "call" and re.search(r"\[rax\s*\+\s*0x28\]", ins.op_str.lower()):
            widths.append(last_width)
            objects.append(aliases.get("rdx"))
            last_width = None
    return objects


def build_reader_maps(pe, md, layouts, rw):
    rw_by_type = {r["type_id"]: r for r in rw.get("results", [])}
    maps = {}
    for layout in layouts.get("layouts", []):
        tid = layout["type_id"]
        body = layout.get("reader_body")
        derived = reader_objects(pe, md, int(body, 16)) if body else []
        existing = rw_by_type.get(tid, {}).get("obj_seq") or []
        size = max(len(derived), len(existing))
        merged = []
        for i in range(size):
            v = derived[i] if i < len(derived) else None
            if v is None and i < len(existing):
                v = existing[i]
            merged.append(v)
        maps[tid] = merged
    return maps


def apply_reader_corroboration(records, layouts, objects_by_type):
    known = set()
    ranges = set()
    for layout in layouts.get("layouts", []):
        seq = objects_by_type.get(layout["type_id"], [])
        for archive in layout.get("archives", {}).values():
            start = (archive.get("window") or [0, 0])[0]
            for field in archive.get("fields", []):
                idx = start + field["idx"]
                oo = seq[idx] if idx < len(seq) else None
                if isinstance(oo, int):
                    known.add((oo, field["width"]))
                    ranges.add((oo, field["width"], layout["type_id"]))
    for rec in records:
        off, size = rec["object_off"], rec["size"]
        if (off, size) in known:
            rec["score"] = min(0.99, round(rec["score"] + 0.065, 3))
            rec["why"] += "; reader obj_seq 同偏移/宽度"
        elif size == 4 and any(o <= off < o + w and w == 8 for o, w, _ in ranges):
            rec["score"] = min(0.98, round(rec["score"] + 0.04, 3))
            rec["why"] += "; reader 8B 槽内子字段"
    return records


def reduce_table(records, limit=4):
    by_code = defaultdict(list)
    for r in records:
        by_code[r["code"]].append(r)
    table = {}
    for code, vals in by_code.items():
        # Keep the strongest evidence for each distinct location/width/kind, then cap candidate count.
        uniq = {}
        for r in vals:
            k = (r["object_off"], r["size"], r["kind"])
            if k not in uniq or r["score"] > uniq[k]["score"]:
                uniq[k] = r
        ranked = sorted(uniq.values(), key=lambda r: (-r["score"], r["object_off"], r["file_off"]))[:limit]
        table[code] = [{k: v for k, v in r.items() if not k.startswith("_") and k != "code"} for r in ranked]
    return dict(sorted(table.items()))


def make_naming(layouts, objects_by_type, table):
    # Include only evidence that has an actual reader location/width match or a direct subfield overlap.
    records = []
    for code, vals in table.items():
        for v in vals:
            records.append({"code": code, **v})
    results = []
    for layout in layouts.get("layouts", []):
        tid = layout["type_id"]
        seq = objects_by_type.get(tid, [])
        archives = {}
        for arch, spec in layout.get("archives", {}).items():
            start = (spec.get("window") or [0, 0])[0]
            fields = []
            for f in spec.get("fields", []):
                seq_idx = start + f["idx"]
                obj_off = seq[seq_idx] if seq_idx < len(seq) else None
                slot_w = f["width"]
                exact = [r for r in records if r["object_off"] == obj_off and r["size"] == slot_w]
                parts = []
                if slot_w == 8 and isinstance(obj_off, int):
                    parts = [r for r in records if r["size"] == 4 and obj_off <= r["object_off"] < obj_off + 8]
                    parts.sort(key=lambda r: (r["object_off"], -r["score"], r["code"]))
                    part_codes = []
                    covered = set()
                    for r in parts:
                        if r["score"] >= 0.84 and r["code"] not in part_codes:
                            part_codes.append(r["code"])
                            covered.add(r["object_off"])
                    # An 8B packed reader slot may be named from its two adjacent 4B scalar getters.
                    if len(covered) >= 2:
                        exact = [r for r in parts if r["code"] in part_codes]
                exact.sort(key=lambda r: (-r["score"], r["kind"] != "read", r["code"]))
                accepted = [r for r in exact if r["score"] >= 0.84]
                codes = []
                for r in accepted:
                    if r["code"] not in codes:
                        codes.append(r["code"])
                if codes:
                    confidence = "readpair"
                    why = [r["why"] for r in accepted if r["code"] in codes]
                else:
                    confidence = "unresolved"
                    why = []
                # Preserve the reader-derived slot coordinates verbatim.
                fields.append({
                    "idx": f["idx"], "row_off": f["row_off"], "width": f["width"],
                    "object_off": obj_off,
                    "field": "+".join(codes) if codes else None,
                    "codes": codes,
                    "confidence": confidence,
                    "accesses": [{"code": r["code"], "object_off": r["object_off"], "size": r["size"],
                                  "kind": r["kind"], "file_off": r["file_off"], "access_va": r["access_va"],
                                  "score": r["score"], "why": r["why"]}
                                 for r in accepted if r["code"] in codes],
                    "why": why,
                })
            archives[arch] = {"business_width": spec["business_width"], "window": spec.get("window"), "fields": fields}
        results.append({"type_id": tid, "entity": layout.get("entity"), "reader_body": layout.get("reader_body"),
                        "archives": archives})
    return {"note": "字段名来自全局 4CC cmp 分发链的窄读/窄写证据，并按 reader obj_seq 的 object_off 连接；row_off/width 原样保留。",
            "entities": len(results), "results": results}


def selftest():
    assert code_from_imm(b"talC") == "Clat"
    assert code_from_imm(b"\x00abc") is None
    assert SIZE["dword"] == 4 and OFF_MIN == 0x20
    print("build.py selftest: OK")
    return 0


def main():
    ap = argparse.ArgumentParser(description="Build the global 4CC field table and layout naming result.")
    ap.add_argument("--outdir", default=str(OUT))
    ap.add_argument("--selftest", action="store_true")
    args = ap.parse_args()
    if args.selftest:
        return selftest()
    outdir = Path(args.outdir)
    outdir.mkdir(parents=True, exist_ok=True)
    # Keep the required in-progress marker durable while the expensive build runs.
    (outdir / "4cc_table.json").write_text('{"status":"in_progress"}\n', encoding="utf-8")
    pe = load_pe()
    layouts = json.loads(LAYOUTS.read_text(encoding="utf-8"))
    rw = json.loads(READER_WIDTHS.read_text(encoding="utf-8"))
    hits, md = decode_cmp_hits(pe)
    print(f"validated cmp hits={len(hits)}, distinct codes={len({h[1] for h in hits})}")
    objects = build_reader_maps(pe, md, layouts, rw)
    recs = find_candidates(pe, hits, md)
    recs = apply_reader_corroboration(recs, layouts, objects)
    table = reduce_table(recs)
    result = {
        "status": "complete_with_unresolved",
        "note": "Global executable scan of verified cmp imm32 4CC instructions; candidates require narrow direct read or narrow setter write. Candidate ranks combine branch strength and generic reader-offset corroboration.",
        "exe_sha256": hashlib.sha256(pe.raw).hexdigest(),
        "scan": {"validated_cmp_hits": len(hits), "distinct_4cc_cmp_codes": len({h[1] for h in hits}),
                 "codes_with_narrow_access": len(table), "candidate_records": sum(map(len, table.values()))},
        "codes": table,
    }
    (outdir / "4cc_table.json").write_text(json.dumps(result, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")
    naming = make_naming(layouts, objects, table)
    naming["exe_sha256"] = result["exe_sha256"]
    (outdir / "naming_result.json").write_text(json.dumps(naming, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")
    print(f"narrow-access codes={len(table)}, evidence={sum(map(len, table.values()))}; entities={naming['entities']}")
    for code in ("Clat", "Clon", "Cnti", "Cwea", "Clgi", "Clri", "icla", "iscl", "Imnd", "Iexd", "Iiar", "Irec", "Iocr", "Imip", "Iagr", "Icms", "Icon", "inSr", "Icdp"):
        print(code, table.get(code, []))
    return 0


if __name__ == "__main__":
    sys.exit(main())

