                matched = []
                for r in records:
                    if r["code"] not in allowed or r["score"] < 0.84:
                        continue
                    if not plausible_schema_width(r["code"], r["size"], types_by_code):
                        continue
                    exact = r["object_off"] == obj_off and r["size"] == width
