                    # Multiple one-byte boolean tags can legitimately share a packed byte.
                    bit_tags = width == 1 and all("boolean" in types_by_code.get(r["code"], set()) for r in choices)
                    if not bit_tags:
                        choices.sort(key=lambda r: (-r["score"], r["code"]))
